python3 - "$LOG" "$OUT" "$TS" "$ACCOUNT_ID" <<'PYEOF'
import json, sys, os
log_path, out_dir, ts, acct = sys.argv[1], sys.argv[2], sys.argv[3], sys.argv[4]
cmds, fails, digest = {}, {}, []
for line in open(log_path):
    line = line.strip()
    if not line or line.startswith('command'): continue
    parts = line.rsplit('\t', 1)
    if len(parts) != 2: continue
    cmd, rc = parts[0], int(parts[1])
    st = 'skip' if rc == -1 else ('pass' if rc == 0 else 'fail')
    cmds[cmd] = st
    if st == 'fail': fails[cmd] = rc
    fn = cmd.replace(' ', '_').replace('/', '_')
    so = open(os.path.join(out_dir, fn+'.stdout')).read() if os.path.exists(os.path.join(out_dir, fn+'.stdout')) else ''
    se = open(os.path.join(out_dir, fn+'.stderr')).read() if os.path.exists(os.path.join(out_dir, fn+'.stderr')) else ''
    digest.append({'command': cmd, 'exit_code': rc, 'status': st, 'stdout': so, 'stderr': se})
pa = sum(1 for v in cmds.values() if v == 'pass')
fa = sum(1 for v in cmds.values() if v == 'fail')
sk = sum(1 for v in cmds.values() if v == 'skip')
r = {'timestamp': ts, 'account_id': acct, 'total': len(cmds), 'pass': pa, 'fail': fa, 'skip': sk,
     'commands': cmds, 'failures': fails}
json.dump(r, open(os.path.join(out_dir, 'results.json'), 'w'), indent=2)
with open(os.path.join(out_dir, 'digest.ndjson'), 'w') as f:
    for e in digest: f.write(json.dumps(e) + "\n")

# Build digest.md — per-product table sorted by most failures, plus failure details
products = {}
for e in digest:
    parts = e['command'].replace('cf ', '').split()
    prod = parts[0] if parts else 'unknown'
    products.setdefault(prod, {'pass': 0, 'fail': 0, 'failures': []})
    if e['status'] == 'pass': products[prod]['pass'] += 1
    elif e['status'] == 'fail':
        products[prod]['fail'] += 1
        se = e.get('stderr', '').strip()
        err = ''
        for ln in se.split('\n'):
            ln = ln.strip()
            if ln and ('API Error' in ln or 'error' in ln.lower()): err = ln[:120]; break
        if not err:
            for ln in se.split('\n'):
                if ln.strip(): err = ln.strip()[:120]; break
        products[prod]['failures'].append((e['command'], err))

def cat(err):
    if '400' in err: return '400'
    if '401' in err: return '401'
    if '403' in err: return '403'
    if '404' in err: return '404'
    if '405' in err: return '405'
    if '500' in err: return '500'
    if not err: return 'other'
    return 'cli'

def sumf(failures):
    cs = {}
    for c, e in failures: cs[cat(e)] = cs.get(cat(e), 0) + 1
    return ', '.join(f'{v}x {k}' for k, v in sorted(cs.items(), key=lambda x: -x[1]))

md = []
md.append('# E2E Test Results')
md.append('')
md.append(f'**Run:** {ts}')
md.append(f'**Account:** `{acct}`')
md.append(f'**Total:** {len(cmds)} | **Pass:** {pa} | **Fail:** {fa}')
md.append('')
md.append('## Per-Product Results')
md.append('')
md.append('| Product | Pass | Fail | Notes |')
md.append('|---------|------|------|-------|')
for prod in sorted(products, key=lambda p: -products[p]['fail']):
    p = products[prod]
    notes = sumf(p['failures']) if p['fail'] > 0 else ''
    md.append(f'| {prod} | {p["pass"]} | {p["fail"]} | {notes} |')
md.append('')
md.append('## Failure Details')
md.append('')
for prod in sorted(products, key=lambda p: -products[p]['fail']):
    p = products[prod]
    if not p['failures']: continue
    md.append(f'### {prod} ({p["fail"]} failures)')
    md.append('')
    md.append('| Command | Error |')
    md.append('|---------|-------|')
    for cmd, err in p['failures']:
        md.append(f'| `{cmd}` | {err} |')
    md.append('')
md.append('')
md.append('## Failure Categories')
md.append('')
gcats = {}
for p in products.values():
    for c, e in p['failures']: gcats[cat(e)] = gcats.get(cat(e), 0) + 1
md.append('| Category | Count |')
md.append('|----------|-------|')
labels = {'400': '400 Bad Request', '401': '401 Unauthorized', '403': '403 Forbidden', '404': '404 Not Found', '405': '405 Method Not Allowed', '500': '500 Internal Server Error', 'cli': 'CLI error', 'other': 'Other'}
for c in sorted(gcats, key=lambda x: -gcats[x]):
    md.append(f'| {labels.get(c, c)} | {gcats[c]} |')
md.append('')
md.append('## All Commands')
md.append('')
md.append('| # | Status | Command | stdout | stderr |')
md.append('|---|--------|---------|--------|--------|')
for i, e in enumerate(digest, 1):
    fn = e['command'].replace(' ', '_').replace('/', '_')
    icon = '\u2705' if e['status'] == 'pass' else ('\u23ed' if e['status'] == 'skip' else '\u274c')
    md.append(f'| {i} | {icon} {e["status"]} | `{e["command"]}` | [{fn}.stdout]({fn}.stdout) | [{fn}.stderr]({fn}.stderr) |')
md.append('')
with open(os.path.join(out_dir, 'digest.md'), 'w') as f: f.write('\n'.join(md) + '\n')
print(f'  results.json + digest.ndjson + digest.md written ({len(cmds)} commands)')
PYEOF